// The home base: draws the shell (public/models/base/shell.glb) and places the furniture and machines
// from hall.glb, greenhouse.glb and exterior.glb where shared/base.ts lays them out (the same layout the
// physics collides with). Models are generated by tools/blender/base/*.py.
//
// Glass is see-through and casts no shadow, so the sun reaches the greenhouse beds and the dome's
// oculus. Warm point lights keep the inside readable at night. Rotors on the condenser and wind pump turn.
import * as THREE from 'three/webgpu';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { BASE, BASE_PIECES } from '../../shared/base.ts';

const GLBS = ['shell', 'hall', 'greenhouse', 'exterior'] as const;

/** Interior lights, local to the hall centre: [x, y, z, colour, intensity, distance]. */
const LIGHTS: [number, number, number, number, number, number][] = [
  [0, 4.4, 0, 0xffc080, 16, 16], // chandelier
  [-13.6, 3.2, 0, 0xffe6b0, 10, 14], // grow lamps
];

export class Base {
  readonly group = new THREE.Group();
  private rotors: { obj: THREE.Object3D; axis: 'y' | 'z'; speed: number }[] = [];

  constructor(scene: THREE.Scene) {
    this.group.position.set(BASE.x, BASE.y, BASE.z);
    scene.add(this.group);
    for (const [x, y, z, colour, intensity, distance] of LIGHTS) {
      const l = new THREE.PointLight(colour, intensity, distance, 1.5);
      l.position.set(x, y, z);
      this.group.add(l);
    }
    const loader = new GLTFLoader();
    for (const name of GLBS) {
      loader.load(
        `./models/base/${name}.glb`,
        (gltf) => this.place(name, gltf.scene),
        undefined,
        (err) => console.warn(`base: failed to load ${name}.glb`, err),
      );
    }
  }

  private place(glb: (typeof GLBS)[number], root: THREE.Object3D) {
    prepare(root);
    if (glb === 'shell') {
      this.group.add(root);
      return;
    }
    for (const p of BASE_PIECES) {
      if (p.glb !== glb) continue;
      const src = root.getObjectByName(p.node);
      if (!src) {
        console.warn(`base: no node ${p.node} in ${glb}.glb`);
        continue;
      }
      const o = src.clone();
      o.position.set(p.x, p.y ?? 0, p.z);
      o.rotation.set(0, Math.atan2(p.fx, p.fz), 0);
      this.group.add(o);
      o.traverse((c) => {
        if (c.name.endsWith('condenser_rotor')) this.rotors.push({ obj: c, axis: 'y', speed: 0.6 });
        if (c.name.endsWith('windpump_rotor')) this.rotors.push({ obj: c, axis: 'z', speed: 1.4 });
      });
    }
  }

  /** Spin the rotors; `windiness` 0..1 speeds them up. */
  update(dt: number, windiness: number) {
    const k = 0.4 + 1.6 * windiness;
    for (const r of this.rotors) r.obj.rotation[r.axis] += r.speed * k * dt;
  }
}

/** Shadows on, glass see-through and shadowless, emissive bits glowing. */
function prepare(root: THREE.Object3D) {
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const mats = Array.isArray(m.material) ? m.material : [m.material];
    const glass = mats.some((mt) => mt.name.startsWith('Glass'));
    m.castShadow = !glass;
    m.receiveShadow = true;
    for (const mt of mats as THREE.MeshStandardMaterial[]) {
      if (mt.name.startsWith('Glass')) {
        mt.transparent = true;
        mt.opacity = 0.22;
        mt.depthWrite = false;
        mt.side = THREE.DoubleSide;
        mt.roughness = 0.05;
        mt.metalness = 0;
      } else if (mt.name.startsWith('Emit') && mt.emissive) {
        mt.emissiveIntensity = Math.max(mt.emissiveIntensity, 2);
      }
    }
  });
}
